sys_script_include.script:
function GetDeploymentTaskSupportedExecution(strAction)
{
	var ArrayValueExists = x_snc_devtools.ArrayValueExists;

	var aAutomatic = [
		'plugin_install',
		'plugin_update',
		'store_app_install',
		'store_app_update',
		'install_switch_branch',
		'install_apply_remote_changes',
		'install_import_from_source_control',
		'run_codesanity',
		'run_install_scripts',
		'run_atf_test_suite'
		];

	if (ArrayValueExists(aAutomatic,strAction) == true)
	{
		return 'automatic';
	}
	return 'manual';
}
